from lib import *
recs=[]
recs.append(R(6470032,"بجٹ کے موافق سبزی برگر آم کے سلاد کے ساتھ","اس سبزی خور ڈش کو کٹے ہوئے ٹماٹر اور تازہ موزاریلا پنیر کے سلاد کے ساتھ پیش کریں۔","6","1 برگر + ¼ کپ سلاد",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1 (15 اونس) ڈبہ کینیلینی بینز (دھوئی ہوئی اور پانی نکالی ہوئی)","1/2 کپ پیاز (کٹی ہوئی)","1 جوا لہسن (باریک کٹا ہوا)","1 کپ سفید (بٹن) مشروم (کٹے ہوئے)","1 کپ کدوکش کی ہوئی گاجر","1 کھانے کا چمچ ورسٹرشائر ساس","1 کھانے کا چمچ کم سوڈیم والی سویا ساس","1 کپ فوری پکنے والا جئی کا دلیہ (اوٹس)","2 چائے کے چمچ اسٹیک مسالا","1 درمیانا کچا آم (چھلا ہوا، گٹھلی نکلا ہوا اور کدوکش کیا ہوا)","1 (9 اونس) پیکٹ تیار کول سلا مکس","2 کھانے کے چمچ رائس وائن سرکہ","1 کھانے کا چمچ زیتون کا تیل","6 پتے لیٹس (بڑے)"],
["ایک بڑے نان اسٹک سوتے پین پر کوکنگ اسپرے لگائیں۔ ایک طرف رکھ دیں۔","کینیلینی بینز، پیاز، لہسن، مشروم، گاجر، ورسٹرشائر ساس، سویا ساس، اوٹس، مونٹریال اسٹیک مسالا اور نمک (اختیاری) کو فوڈ پروسیسر میں ڈالیں۔ کئی بار پلس کریں تاکہ مرکب مل جائے لیکن پیسٹ نہ بنے۔","برگر کے مرکب کو 6 برابر حصوں میں تقسیم کریں اور ٹکیاں بنا لیں۔","تیار کیے ہوئے سوتے پین کو درمیانی تیز آنچ پر گرم کریں۔ برگرز کو ہر طرف 6-8 منٹ تک سوتے کریں۔ ایک طرف رکھ دیں۔","ایک بڑے پیالے میں کدوکش کیا ہوا آم، کول سلا مکس، رائس وائن سرکہ اور زیتون کا تیل ملائیں۔ اچھی طرح ملا لیں تاکہ سب پر لگ جائے۔","ایک برگر لیٹس کے پتے پر رکھیں اور اس پر 3/4 کپ کول سلا مکسچر ڈالیں۔"]))
recs.append(R(6470482,"چکن انناس اور مینڈرن سنگترے کی سالسا کے ساتھ","کک بک کی مصنفہ رابن ویب کہتی ہیں، \"بچپن میں مجھے تازہ پھل زیادہ پسند نہیں تھے۔ لیکن ڈبے والے مینڈرن سنگترے مجھے ہمیشہ خوش کرتے تھے اور مجھے کٹ گلاس کا وہ چھوٹا سا پیالہ یاد ہے جس میں میری ماں سنگترے کی ننھی پھانکیں پیش کرتی تھیں۔ اب میں نے یقیناً اپنے پھلوں کا دائرہ وسیع کر لیا ہے، لیکن میرے خیال میں مینڈرن سنگترے اب بھی ایک بہترین ہمہ جہت پھل ہیں۔ یہاں ناریل کے ذائقے والی ایک سادہ سالسا زیرے کے ذائقے والے سیئر کیے ہوئے چکن بریسٹ کے ساتھ خوب جچتی ہے۔\"","4","1 بریسٹ + 1/2 کپ سالسا",
["1 کپ ڈبے کا انناس (بغیر اضافی چینی، اچھی طرح نچوڑا ہوا)","1 کپ پانی یا جوس میں پیک کیے ہوئے مینڈرن سنگترے (اچھی طرح نچوڑے ہوئے، موٹے کٹے ہوئے)","2 ڈنڈی ہری پیاز (صرف سفید حصہ، باریک کٹا ہوا)","1/4 کپ لال شملہ مرچ (باریک کٹی ہوئی)","1 1/2 کھانے کے چمچ بغیر میٹھے ناریل کے ٹکڑے","1/4 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس","1 پاؤنڈ بغیر ہڈی اور بغیر کھال کے چکن بریسٹ","1 چائے کا چمچ پسا ہوا زیرہ","1 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر)","1/4 چائے کا چمچ کوشر نمک","1/8 چائے کا چمچ کالی مرچ","1 کھانے کا چمچ سبزیوں کا تیل"],
["بیکنگ شیٹ پر ورق (فوائل) بچھائیں۔ اوون کو 375 ڈگری F پر پہلے سے گرم کریں۔ سالسا کے تمام اجزاء کو ایک پیالے میں ملا لیں۔ ڈھانپ کر 1 گھنٹے کے لیے فریج میں رکھ دیں۔","اس دوران چکن بریسٹ سے زائد چربی کاٹ کر الگ کر دیں۔ زیرہ، لال مرچ پاؤڈر، نمک اور کالی مرچ کو ملا لیں۔ چکن کے ہر ٹکڑے پر یہ مسالا اچھی طرح مل دیں۔","ایک بڑے فرائنگ پین میں تیل کو درمیانی تیز آنچ پر گرم کریں۔ چکن ڈالیں اور دونوں طرف سے کل 10 منٹ تک سیئر کریں۔ چکن کو تیار بیکنگ شیٹ پر رکھ دیں۔ ہلکے سے فوائل یا پارچمنٹ پیپر سے ڈھانپ دیں۔ چکن بریسٹ کو اندر تک پکنے تک پکاتے رہیں، تقریباً 6–7 منٹ۔","سالسا کو کمرے کے درجہ حرارت پر آنے دیں۔ پکا ہوا چکن سالسا کے ساتھ پیش کریں۔"]))
recs.append(R(6471870,"ٹوفو، مشروم اور بوک چوئے رامین","رامین پسند ہے؟ یہ ہلکا پھلکا سبزی خور متبادل آزمائیں! اگر آپ کو مسالے دار رامین پسند ہے تو تھوڑی سی سری راچا ڈال لیں۔","4","2 کپ",
["4 اونس خشک رامین نوڈلز","1 کھانے کا چمچ تل کا تیل","1 درمیانی پیلی پیاز (باریک کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","1 کھانے کا چمچ تازہ ادرک (کدوکش کیا ہوا)","3 کپ کم سوڈیم والا سبزیوں کا شوربہ","2 کپ پانی","1 کپ شیٹاکے مشروم (کٹے ہوئے)","1 کپ بروکلی (پھولے)","4 ڈنڈی بیبی بوک چوئے (کٹی ہوئی)","5 اونس گاجر (کدوکش کی ہوئی)","14 اونس ایکسٹرا فرم ٹوفو (پانی نکالا ہوا، دبایا ہوا اور چکور ٹکڑوں میں کٹا ہوا)","1 1/2 کھانے کے چمچ کوکونٹ امینوز","1 کھانے کا چمچ رائس سرکہ","2 ڈنڈی ہری پیاز (کٹی ہوئی)"],
["رامین نوڈلز کو پیکٹ پر دی گئی ہدایت کے مطابق ابال لیں۔ پانی نتھار کر ایک طرف رکھ دیں۔","ایک بڑے برتن میں تل کا تیل درمیانی آنچ پر گرم کریں۔ کٹی ہوئی پیاز، باریک کٹا لہسن اور کدوکش کیا ہوا ادرک ڈالیں۔ پیاز کے شفاف ہونے تک سوتے کریں۔","سبزیوں کا شوربہ اور پانی ڈال کر ہلکی آنچ پر اُبال آنے دیں۔","کٹے ہوئے مشروم، بروکلی کے پھولے، کٹی ہوئی بوک چوئے، کدوکش کی ہوئی گاجر اور چکور کٹا ہوا ٹوفو برتن میں ڈالیں۔ تقریباً 5–7 منٹ تک ہلکی آنچ پر پکائیں، جب تک سبزیاں نرم نہ ہو جائیں۔","کوکونٹ امینوز اور رائس سرکہ ملا دیں۔","پکے ہوئے رامین نوڈلز کو پیش کرنے والے پیالوں میں تقسیم کریں۔ سبزیوں سے بھرپور شوربہ نوڈلز پر ڈالیں اور ہری پیاز سے سجائیں۔"]))
recs.append(R(6472756,"جمیکن بھری ہوئی مچھلی رٹز کے ساتھ","یہ ترکیب ہمارے خاندان کی پسندیدہ ہے۔ عام طور پر ییلو ٹیل اسنیپر یا پیرٹ فش پوری مچھلی کو بھر کر، کیلے کے پتے کی پٹیوں سے باندھ کر، بڑی لکڑیوں پر رکھا جاتا ہے جہاں اسے کھلی آگ پر پکایا جاتا ہے۔","4","1/2 ٹراؤٹ (تقریباً 5 اونس)",
["2 چھوٹی یا 4 فلیٹس (کھال سمیت) پوری ٹراؤٹ (یا اسنیپر استعمال کریں، صاف کی ہوئی، چھلکے اتارے ہوئے، اور آڑے ترچھے کٹ لگے ہوئے)","2 اسپرے، 0.5 گرام نان اسٹک ایکسٹرا ورجن زیتون کے تیل کا اسپرے","1 لیموں کا رس (1 لیموں سے)","1 چٹکی کوشر نمک (ذائقے کے مطابق)","1/2 کپ سالم گندم کے کریکرز (کٹے ہوئے/چورا کیے ہوئے)","1/2 کپ سالم گندم کے رٹز کریکرز (چورا کیے ہوئے)","1 چائے کا چمچ تازہ تھائم (باریک کٹا ہوا)","1 عدد تیز مرچ (بیج نکلی ہوئی اور باریک کٹی ہوئی، جیسے اسکاچ بونٹ، سیرانو یا ہالاپینو)","1 گڈی (~5 ڈنڈی) ہری پیاز (کٹی ہوئی)","1 کھانے کا چمچ مارجرین (مکھن نما اسپریڈ، پگھلایا ہوا)"],
["تیز چاقو سے مچھلی کی کھال پر کٹ لگائیں۔ مچھلی کی کٹی ہوئی سطح پر کوکنگ اسپرے کریں۔ کھال پر لیموں نچوڑیں اور نمک چھڑکیں۔ سطح پر اچھی طرح مل دیں۔","چورا کیے ہوئے کریکرز، تھائم، تیز مرچ، ہری پیاز اور پگھلا ہوا مکھن ایک درمیانے پیالے میں ملا کر بھرائی تیار کریں۔ مچھلی کے پیٹ میں یہ بھرائی بھر دیں، اور ٹوتھ پک یا دھاتی سیخ کی مدد سے سیخ کو بُنتے ہوئے منہ بند کر دیں۔ آپ مضبوطی کے لیے مچھلی کے نیچے 2 انچ کے فاصلے پر ٹوتھ پکس بھی لگا سکتے ہیں۔","گرِل کو درمیانی تیز آنچ پر پہلے سے گرم کریں اور مچھلی کو گرِل کی جالی پر رکھیں۔ 15–18 منٹ تک پکائیں، وقفے وقفے سے پلٹتے رہیں، جب تک مچھلی اندر تک پک نہ جائے اور باہر سے کرکری نہ ہو جائے۔"]))
recs.append(R(6473360,"سلو کوکر گلوٹین فری پالک لزانیہ","یہ ترکیب فوری، مزیدار اور آسان کھانا ہے جسے پورا خاندان پسند کرے گا۔ اسے ضرور آزمائیں!","12","1 ٹکڑا (ترکیب کا 1/12)",
["9 عدد لزانیہ نوڈلز (گلوٹین فری)","24 1/2 اونس بوتل بند پاستا ٹماٹر ساس (کم سوڈیم)","1 پیکٹ منجمد پالک (10 اونس، کٹی ہوئی، پگھلائی ہوئی اور پانی نچوڑا ہوا)","1 کپ پارٹ اسکم موزاریلا پنیر (کدوکش کیا ہوا، تقسیم شدہ)","1 کپ کم چکنائی والا ریکوٹا پنیر","1 عدد نان اسٹک کوکنگ اسپرے","1/4 کپ پارمیزان پنیر (تازہ کدوکش کیا ہوا)","8 اونس ٹماٹر ساس (1 عدد 8 اونس کا ڈبہ، بغیر نمک اضافے کے)"],
["سلو کوکر پر کوکنگ اسپرے کریں۔","ایک درمیانے پیالے میں ریکوٹا پنیر، پارمیزان پنیر، 1/4 کپ موزاریلا پنیر اور پالک ملا لیں۔","سلو کوکر کی تہہ میں 1 کپ پاستا ساس پھیلائیں۔ ساس کے اوپر 3 نوڈلز پہلو بہ پہلو رکھیں؛ ضرورت ہو تو فٹ کرنے کے لیے نوڈلز توڑ لیں۔","نوڈلز کے اوپر ریکوٹا اور پالک کے مرکب کا تقریباً 1/3 کپ پھیلائیں۔ پاستا ساس، نوڈلز اور ریکوٹا پالک مرکب کی تہیں مزید 2 بار دہرائیں۔ اوپر بچی ہوئی پاستا ساس اور ڈبے کی ٹماٹر ساس ڈالیں۔ اوپر 1 کپ موزاریلا پنیر چھڑکیں۔","سلو کوکر کا ڈھکن لگا دیں۔ کم (low) سیٹنگ پر 2–3 گھنٹے یا پکنے تک پکائیں (سلو کوکر کے لحاظ سے پکنے کا وقت مختلف ہو سکتا ہے)۔","* اس ترکیب کو گلوٹین فری لزانیہ نوڈلز کے ساتھ آزمایا گیا ہے، لیکن سالم گندم کے لزانیہ نوڈلز بھی استعمال کیے جا سکتے ہیں۔"]))
recs.append(R(6474350,"کٹے ہوئے بادام","کٹے ہوئے بادام کی غذائی معلومات","1","1/2 اونس",["1/2 اونس کٹے ہوئے بادام"],[]))
recs.append(R(6475348,"سسلی کا زیتون سلاد","یہ کچلے ہوئے زیتونوں کا مرکب ہمارے خاندان کی پسندیدہ ڈش ہے جو کیلابریا اور سسلی دونوں میں مقبول ہے۔ سسلی کے کاسٹیلویترانو زیتون اب بڑے سپر مارکیٹوں میں آسانی سے مل رہے ہیں، اور اگر آپ کو دستیاب ہوں تو یہ اس سلاد کے لیے بہترین انتخاب ہیں۔ بہت سی اطالوی-امریکی ڈیلیز \"سسلین کولوسل\" زیتون بھی بیچتی ہیں، جو اتنے ہی اچھے رہتے ہیں۔ سردیوں میں آپ اس مرکب کے چند کھانے کے چمچ گرم پاستا میں، یا گرم موسم میں ٹھنڈے چاول یا کینوا میں ملا سکتے ہیں۔ یہ عام سبزیوں، سمندری غذا اور گوشت کو مزیدار بنانے کا بھی بہترین طریقہ ہے۔\n\nیہ ترکیب The Mediterranean Diabetes Cookbook سے لی گئی ہے۔","16","2 کھانے کے چمچ",
["1/2 پاؤنڈ بڑے ہرے زیتون (اچھی طرح دھوئے ہوئے، پانی نکالے ہوئے اور خشک رگڑے ہوئے)","5 ڈنڈی اجوائن (چکور کٹی ہوئی)","2 درمیانی گاجریں (چھلی ہوئی اور چکور کٹی ہوئی)","1 چھوٹی لال پیاز (چکور کٹی ہوئی)","3 جوے لہسن","2 چائے کے چمچ خشک اوریگانو","1/2 چائے کا چمچ کالی مرچ","1/8 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس","1/4 کپ ایکسٹرا ورجن زیتون کا تیل"],
["زیتونوں کو کٹنگ بورڈ پر رکھیں۔ صاف کچن تولیے سے ڈھانپ دیں اور گوشت کوٹنے والے ہتھوڑے یا فرائنگ پین کی پشت سے انہیں ہلکا سا کچل دیں۔ (مقصد زیتونوں کو تھوڑا سا کچلنا ہے۔)","زیتونوں کو ایک پیالے میں ڈالیں اور باقی اجزاء کے ساتھ ملا لیں۔","سلاد کو کمرے کے درجہ حرارت پر ایک گھنٹے تک میرینیٹ ہونے دیں، یا ڈھانپ کر فریج میں کم از کم 1 دن اور زیادہ سے زیادہ 3 دن تک ٹھنڈا کریں۔ پیش کرنے سے پہلے سلاد کو کمرے کے درجہ حرارت پر لے آئیں۔"]))
recs.append(R(6475917,"دہی کا رینچ ڈریسنگ","گھر کی بنی ہوئی چیز کا کوئی مقابلہ نہیں، رینچ ڈریسنگ بھی اس میں شامل ہے! کریمی دہی پروٹین فراہم کرتا ہے، لیکن اس ذیابیطس کے لیے موزوں سلاد ڈریسنگ میں اصل کمال تازہ جڑی بوٹیوں کا ہے۔","8","2 کھانے کے چمچ",
["1 کپ سادہ بغیر چکنائی والا یونانی دہی","2 کھانے کے چمچ تازہ چائیوز (باریک کٹے ہوئے)","2 کھانے کے چمچ تازہ پارسلے (باریک کٹا ہوا)","1 جوا لہسن (باریک کٹا ہوا)","1 چائے کا چمچ پیاز پاؤڈر","1 چائے کا چمچ خشک ڈل","1 چائے کا چمچ ڈیجون رائی","1 کھانے کا چمچ سیب کا سرکہ","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["ایک درمیانے پیالے میں یونانی دہی، چائیوز، پارسلے، لہسن، پیاز پاؤڈر، خشک ڈل، ڈیجون رائی، سیب کا سرکہ، نمک اور کالی مرچ ملا لیں۔","ڈریسنگ کو فریج میں کم از کم 10 منٹ رکھیں تاکہ ذائقے آپس میں مل جائیں۔"]))
recs.append(R(6478767,"اخروٹ، سالم","اخروٹ کی غذائی معلومات","1","1 اونس",["1 اونس اخروٹ"],[]))
recs.append(R(6479129,"جھینگا اور ایوکاڈو ٹیکو باؤلز","پکے ہوئے جھینگے ایک آسان شارٹ کٹ ہیں، یا آپ بچا ہوا جھینگا استعمال کر سکتے ہیں اور اسے رات بھر فریج میں رکھ سکتے ہیں۔ انناس اور ایوکاڈو ان آسان ٹیکو باؤلز کو تازہ اور خوشگوار ذائقہ دیتے ہیں۔","2","1 لیٹس باؤل + 4 اونس جھینگا + تقریباً 1/2 کپ انناس اور ایوکاڈو",
["1/2 پاؤنڈ مکمل پکے ہوئے جھینگے (چھلے ہوئے، آنت نکلی ہوئی، دم ہٹائی ہوئی)","1/4 کپ سالسا","1/2 درمیانا ایوکاڈو (چھلا ہوا اور چکور کٹا ہوا)","1 درمیانا ٹماٹر (چکور کٹا ہوا)","1/4 کپ ہری پیاز (باریک کٹی ہوئی)","1/4 کپ تازہ انناس (باریک چکور کٹا ہوا)","1 کھانے کا چمچ ہالاپینو مرچ (کٹی ہوئی، اختیاری)","2 پتے بیب لیٹس","1/2 چائے کا چمچ لال مرچ پاؤڈر (چلی پاؤڈر)","1/4 کپ سادہ بغیر چکنائی والا یونانی دہی","2 کھانے کے چمچ تازہ ہرا دھنیا (اختیاری)"],
["جھینگے، ایوکاڈو، ٹماٹر، ہری پیاز اور انناس (اور اگر چاہیں تو ہالاپینو) کو ملا لیں۔ ہر لیٹس کے گچھے سے درمیان کے چند پتے نکال دیں تاکہ پیالہ بن جائے۔ جھینگے کا مرکب لیٹس کے گچھوں میں تقسیم کر دیں۔","لال مرچ پاؤڈر کو یونانی دہی میں ملا دیں۔","ہر \"ٹیکو\" باؤل پر یونانی دہی کا مرکب اور سالسا ڈالیں۔ اگر چاہیں تو اوپر کٹا ہوا تازہ ہرا دھنیا چھڑکیں۔"]))
recs.append(R(6480132,"کیلیفورنیا کھجور اور ایکورن اسکواش سلاد","کیلیفورنیا کی کھجوروں کی مٹھاس ارگولا کی تیزی اور ہندوستانی مسالوں کے مرکب گرم مسالا کے ساتھ خوبصورتی سے ملتی ہے، جو اس لبھاونی سائیڈ ڈش میں ذائقے کی گہرائی پیدا کرتا ہے۔ ایکورن اسکواش کی کھال رکھنے سے ڈش میں ساخت اور فائبر بھی بڑھ جاتا ہے۔ آپ ایکورن اسکواش کی جگہ سردیوں کی دوسری اقسام، جیسے ڈیلیکاٹا اسکواش، بھی استعمال کر سکتے ہیں۔","6","2/3 کپ",
["1 عدد ایکورن اسکواش (½ انچ موٹے قتلوں میں کٹا ہوا)","1 کھانے کا چمچ زیتون کا تیل","1 چائے کا چمچ کوشر نمک (تقسیم شدہ)","3/4 چائے کا چمچ گرم مسالا (تقسیم شدہ)","2 کھانے کے چمچ تازہ نچوڑا ہوا سنگترے کا رس","1 کھانے کا چمچ خوبانی کا جام (کم چینی والا)","1/4 چائے کا چمچ کالی مرچ","3/4 کپ کیلیفورنیا کی کھجوریں (گٹھلی نکلی ہوئی اور چار ٹکڑوں میں کٹی ہوئی)","5 کپ ارگولا","1/3 کپ اپنی پسند کے بھنے ہوئے میوے (جیسے پستے، پیکن، اخروٹ یا بادام)"],
["اوون کو 425°F پر پہلے سے گرم کریں اور بیکنگ شیٹ پر فوائل یا پارچمنٹ پیپر بچھا لیں۔","ایک بڑے پیالے میں اسکواش، تیل، ½ چائے کا چمچ نمک اور ½ چائے کا چمچ گرم مسالا ڈال کر اچھی طرح ملا لیں۔ اسکواش کو بیکنگ شیٹ پر ایک تہہ میں رکھیں اور 20 منٹ تک روسٹ کریں، بیچ میں ٹکڑے پلٹ دیں۔","اسی پیالے میں رس، جام، پسی کالی مرچ اور باقی ½ چائے کا چمچ نمک اور ¼ چائے کا چمچ گرم مسالا ڈالیں۔ اچھی طرح پھینٹ لیں۔","پکا ہوا اسکواش اور کھجوریں پیالے میں ڈالیں اور اچھی طرح ملا لیں۔","ارگولا کو ایک بڑے سرونگ پیالے یا تھال میں رکھیں۔ اس پر اسکواش اور کھجوریں ڈالیں۔ اوپر بھنے ہوئے میوے چھڑکیں۔"]))
recs.append(R(6480190,"بھنی ہوئی سبزیوں کا اسٹراٹا","انڈوں پر مبنی یہ مین ڈش دن کے کسی بھی وقت بہترین ہے اور بچا ہوا کھانا اگلے دن آسانی سے ساتھ لے جانے والا لنچ بن سکتا ہے۔","8","اسٹراٹا کا 1/8",
["5-6 اسپرے نان اسٹک کوکنگ اسپرے","8 اونس سفید (بٹن) مشروم (کٹے ہوئے)","1 درمیانا شکر قندی (6 اونس، چھلا ہوا اور چکور کٹا ہوا)","1 درمیانی پیاز (چکور کٹی ہوئی)","1 درمیانی لال شملہ مرچ (بیج نکلی ہوئی اور چکور کٹی ہوئی)","1/2 چائے کا چمچ اسپائک سیزننگ (نمک کے بغیر)","2 بڑے انڈے","4 بڑے انڈوں کی سفیدی","1 چائے کا چمچ رائی (خشک)","2 کھانے کے چمچ تازہ سیج (کٹی ہوئی)","1/2 چائے کا چمچ کالی مرچ","8 سلائس سالم گندم کی ڈبل روٹی (ہر ایک 1.5 اونس)","1/2 کپ پارمیزان پنیر (کدوکش کیا ہوا، تقسیم شدہ)"],
["اوون کو 375°F پر پہلے سے گرم کریں۔ ایک بڑی بیکنگ شیٹ پر کوکنگ اسپرے لگائیں۔","تمام سبزیاں ملا کر بیکنگ شیٹ پر برابر پھیلا دیں۔ سبزیوں پر 5-6 بار کوکنگ اسپرے کریں اور بغیر نمک والی اسپائک سیزننگ چھڑکیں۔","سبزیوں کو 30 منٹ تک روسٹ کریں، پھر ذرا ٹھنڈا ہونے کے لیے ایک طرف رکھ دیں۔","انڈے، انڈوں کی سفیدی، خشک رائی، سیج اور کالی مرچ کو اچھی طرح پھینٹ لیں۔","9x13 انچ کی کیسرول ڈش پر کوکنگ اسپرے لگائیں۔ سالم گندم کی ڈبل روٹی کے چار سلائس ٹکڑوں میں توڑ کر کیسرول ڈش کی تہہ میں بچھا دیں۔ اس پر روسٹ کی ہوئی سبزیوں کا 1/2 حصہ اور 1/4 کپ پارمیزان پنیر ڈالیں۔ ڈبل روٹی، سبزیوں اور پنیر پر انڈوں کے مرکب کا 1/2 حصہ ڈالیں۔","باقی توڑی ہوئی ڈبل روٹی، سبزیوں، پنیر اور انڈوں کے مرکب کے ساتھ تہیں بنانے کا عمل دہرائیں۔ کیسرول کو اسپیچولا سے دبا دیں تاکہ تمام ڈبل روٹی انڈوں کے مرکب کو جذب کر لے۔ اسٹراٹا کو 15 منٹ تک کمرے کے درجہ حرارت پر رکھا رہنے دیں۔","اسٹراٹا کو 30 منٹ تک بیک کریں۔","پیش کرنے کے لیے اسٹراٹا کو لمبائی میں بیچ سے کاٹیں، پھر چوڑائی میں بیچ سے کاٹیں۔ ہر آدھے کو چوڑائی میں ایک بار پھر بیچ سے کاٹیں تاکہ 8 برابر حصے بن جائیں۔"]))
recs.append(R(6481807,"ادرک والا کدو کا بِسک","یہ میٹھا اور نمکین سوپ کدو، ناشپاتی اور تازہ ادرک کو ملا کر ایک کریمی سوپ بناتا ہے جو خزاں کے ٹھنڈے دن میں آپ کو گرمائش دے گا۔ آپ سب کچھ سلو کوکر میں ڈال کر دن بھر پکنے کے لیے چھوڑ سکتے ہیں، تاکہ جب آپ کام سے گھر آئیں تو رات کا کھانا تیار ہو۔ خزاں کے سوپ اور سلاد کے امتزاج کے لیے اس ڈش کو Arugula, Pear, Walnut, & Pecorino Salad کے ساتھ، یا زیادہ بھرپور کھانے کے لیے Tarragon Herbed Chicken and Mushrooms کے ساتھ پیش کریں۔","6","1 کپ سوپ اور 1 کھانے کا چمچ دہی",
["1 (15 اونس) ڈبہ کدو کی پیوری","1 درمیانی سخت ناشپاتی (چھلی ہوئی، بیج نکلی ہوئی اور کٹی ہوئی)","1 1/2 کپ پیاز (چکور کٹی ہوئی)","1 (14.5 اونس) ڈبہ کم سوڈیم والا چکن یا سبزیوں کا شوربہ","1/2 چائے کا چمچ پسا ہوا زیرہ","1/4 چائے کا چمچ پسی ہوئی جائفل","1/4 چائے کا چمچ نمک","1/8 چائے کا چمچ کیین مرچ","2 کپ بغیر چکنائی والا ہاف اینڈ ہاف","1/4 کپ ٹرانس فیٹ سے پاک مارجرین","1 1/2 کھانے کے چمچ کم کیلوری والا براؤن شوگر متبادل","1 کھانے کا چمچ تازہ ادرک (کدوکش کیا ہوا)","6 کھانے کے چمچ سادہ بغیر چکنائی والا یونانی دہی"],
["3 ½ سے 4 کوارٹ کے سلو کوکر پر کوکنگ اسپرے لگائیں۔ کدو، ناشپاتی، پیاز، شوربہ، زیرہ، جائفل، نمک اور کیین مرچ سلو کوکر میں ڈالیں۔ ڈھانپ کر تیز (high) پر 3 ½ گھنٹے، یا کم (low) پر 7 گھنٹے، یا پیاز کے نرم ہونے تک پکائیں۔","کدو کے مرکب کو 1-1 کپ کی مقدار میں بلینڈر میں پیس لیں، اور بلینڈ کرتے وقت ڈھکن کو مضبوطی سے بند رکھنا یقینی بنائیں۔ مرکب کو سلو کوکر میں واپس ڈالیں، دہی کے علاوہ باقی اجزاء ملا دیں۔ ڈھانپ کر تیز (high) پر مزید 30 منٹ پکائیں۔","پیش کرتے وقت اوپر 1 کھانے کا چمچ دہی ڈالیں۔"]))
save(1,recs)
